"""Count words by scanning characters for runs of letters, digits and apostrophes."""


def run(text: str):
    count, inside = 0, False
    for character in text:
        word = character.isalnum() or character == "'"
        count += word and not inside
        inside = word
    return {"result": count, "feedback": None}

