import asyncio
import importlib.util
import pathlib
import unittest

PATH = pathlib.Path(__file__).parents[1] / "src/evertree/processes/candidate_triage/_exec.py"
SPEC = importlib.util.spec_from_file_location("triage_under_test", PATH)
program = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(program)


class Context:
    def __init__(self, ranking):
        self.ranking, self.chosen = ranking, {}

    async def step(self, method, payload, **_):
        if method == "program.compare_candidates":
            return {"ranking": self.ranking}
        self.chosen[payload["candidate"]] = payload["decision"]
        return {"decision": payload["decision"]}


class TriageTest(unittest.TestCase):
    def test_single_verified_candidate_merges(self):
        ctx = Context([{"candidate": "a", "verification": {"status": "verified"}}])
        result = asyncio.run(program.run(ctx, ["a"]))
        self.assertEqual(result["result"], {"a": "merge_branch"})

